<template><section><header class="page-head"><div><p class="eyebrow">VISITOR PASS</p><h2>访客通行</h2><p>登记车牌与到访时段，物业批准后生成有效通行证；同一车牌重叠时段仅允许一张。</p></div><el-button type="primary" @click="dialog=true">登记访客</el-button></header><div class="toolbar"><el-select v-model="status" placeholder="全部状态" clearable @change="load"><el-option v-for="(t,k) in visitorPassStatusText" :key="k" :label="t" :value="k"/></el-select></div><div class="visitor-list"><VisitorPassCard v-for="v in visitorPassStore.items" :key="v.id" :pass="v" :can-approve="canManage&&v.status==='pending'" :can-revoke="revocable(v)" @approve="approve" @revoke="revoke"/><EmptyState v-if="!visitorPassStore.items.length"/></div><el-dialog v-model="dialog" title="登记访客通行"><el-form><el-input v-model="form.plate_no" placeholder="车牌号，如 沪A88888"/><el-input v-model="form.building" placeholder="楼栋，如 1栋"/><el-input v-model="form.unit" placeholder="单元，如 2单元"/><el-input v-model="form.room" placeholder="房号，如 802"/><el-date-picker v-model="range" type="datetimerange" range-separator="至" start-placeholder="到访开始" end-placeholder="到访结束"/></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="submit">提交申请</el-button></template></el-dialog></section></template><script setup lang="ts">import{ref,onMounted}from'vue';import{ElMessage}from'element-plus';import{listVisitorPasses,createVisitorPass,approveVisitorPass,revokeVisitorPass}from'../api/visitorPass';import{visitorPassStore}from'../stores/visitorPassStore';import{visitorPassStatusText}from'../constants/visitorPass';import{usePermission}from'../hooks/usePermission';import type{VisitorPass}from'../types';import VisitorPassCard from'../components/common/VisitorPassCard.vue';import EmptyState from'../components/common/EmptyState.vue';const status=ref(''),dialog=ref(false),range=ref<[Date,Date]|null>(null),form=ref({plate_no:'',building:'',unit:'',room:''});const canManage=usePermission('visitor:manage');async function load(){visitorPassStore.items=await listVisitorPasses(status.value)}function revocable(v:VisitorPass){return(v.status==='pending'||v.status==='approved')&&new Date(v.visit_start).getTime()>Date.now()}async function submit(){if(!range.value){ElMessage.error('请选择到访时段');return}try{await createVisitorPass({...form.value,visit_start:range.value[0].toISOString(),visit_end:range.value[1].toISOString()});ElMessage.success('访客通行申请已提交');dialog.value=false;form.value={plate_no:'',building:'',unit:'',room:''};range.value=null;load()}catch(e){ElMessage.error((e as Error).message)}}async function approve(id:number){try{await approveVisitorPass(id);ElMessage.success('访客通行证已批准')}catch(e){ElMessage.error((e as Error).message)}load()}async function revoke(id:number){try{await revokeVisitorPass(id);ElMessage.success('访客通行证已撤销')}catch(e){ElMessage.error((e as Error).message)}load()}onMounted(load)</script>
